<script setup lang="ts">
import {ref,computed} from 'vue'
import {polarContext,circularScore,seeded,type V3} from '../utils/learningMath'
const angle=ref(60),shift=ref(0),rings=6,sectors=12,rnd=seeded(32)
const points:V3[]=Array.from({length:180},(_,i)=>{const side=i%3;return side===0?[10+rnd()*2,-15+rnd()*30,1+rnd()*4]:side===1?[-16+rnd()*25,17+rnd()*2,2+rnd()*6]:[-20+rnd()*3,-20+rnd()*26,1+rnd()*2]})
const rotated=computed(()=>{const a=angle.value*Math.PI/180;return points.map(([x,y,z])=>[Math.cos(a)*x-Math.sin(a)*y,Math.sin(a)*x+Math.cos(a)*y,z] as V3)}),original=polarContext(points),context=computed(()=>polarContext(rotated.value)),scores=computed(()=>Array.from({length:12},(_,i)=>circularScore(original,context.value,i))),best=computed(()=>scores.value.indexOf(Math.min(...scores.value)))
</script>
<template><svg class="lab-svg" style="height:265px" viewBox="0 0 840 265" role="img" aria-label="Nuage LiDAR et descripteur polaire"><text x="20" y="18">Nuage et secteurs polaires</text><g v-for="r in 6" :key="r"><circle cx="150" cy="145" :r="r*18" fill="none" stroke="#cbd5e1"/></g><line v-for="s in 12" :key="s" x1="150" y1="145" :x2="150+108*Math.cos(s*Math.PI/6)" :y2="145+108*Math.sin(s*Math.PI/6)" stroke="#cbd5e1"/><circle v-for="(p,i) in rotated" :key="i" :cx="150+p[0]*3.6" :cy="145-p[1]*3.6" r="2" :fill="`hsl(${210-p[2]*15},70%,43%)`"/><text x="315" y="18">Référence : hauteur maximale / cellule</text><text x="315" y="152">Requête après décalage circulaire</text><g v-for="(grid,k) in [original,context]" :key="k"><g v-for="(row,r) in grid" :key="r"><rect v-for="(_,s) in row" :key="s" :x="320+s*38" :y="32+k*135+r*15" width="36" height="13" :fill="`hsl(${210-grid[r][(s+(k?shift:0))%12]*18},70%,${grid[r][(s+(k?shift:0))%12]>0?43:94}%)`"/></g></g><text x="320" y="129" class="small">Colonnes : secteurs · lignes : anneaux</text></svg><div class="lab-controls"><label>Rotation LiDAR<input aria-label="Rotation LiDAR" v-model.number="angle" type="range" min="0" max="330" step="30"/>{{angle}}°</label><label>Décalage<input aria-label="Décalage circulaire" v-model.number="shift" type="range" min="0" max="11"/>{{shift}}</label><button class="primary" @click="shift=best">Aligner</button><span>Distance = <b>{{scores[shift].toFixed(3)}}</b></span></div><p class="lab-caption">Une rotation devient un décalage de colonnes. La translation et les occultations modifient aussi le contenu des cellules.</p></template>
